// ---- Easy settings ----
const DAILY_SEND_LIMIT = 20;      // max emails sent per run
const MAX_WEBSITE_LOOKUPS = 10;   // leads WITHOUT an email: how many websites we check for an email each run
// -----------------------

const SKIP = ['sent', 'no email', 'send failed', 'replied', 'bounced', 'do not contact', 'unsubscribed'];
const EMAIL_RE = /[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/i;
const social = /(facebook|instagram|tiktok|twitter|linktr|youtube|whatsapp|wa\.me|yelp|tripadvisor|google)\./i;

const rows = $input.all().map(i => i.json || {});
const status = r => String(r['Outreach Status'] || '').trim().toLowerCase();
const emailOf = r => { const m = String(r['Email'] || '').match(EMAIL_RE); return m ? m[0].toLowerCase() : ''; };
const rank = p => ({ high: 0, medium: 1, low: 2 }[String(p || '').trim().toLowerCase()] ?? 1);

const candidates = rows.filter(r =>
  String(r['Business Name'] || '').trim() &&
  String(r['#'] ?? '').trim() !== '' &&
  !SKIP.includes(status(r))
);

const sorter = (a, b) => rank(a['Priority']) - rank(b['Priority']) || (parseInt(a['#'], 10) || 0) - (parseInt(b['#'], 10) || 0);

const withEmail = candidates.filter(r => emailOf(r)).sort(sorter);
const noEmail = candidates.filter(r => !emailOf(r) && String(r['Website'] || '').trim()).sort(sorter);

const picked = [...withEmail.slice(0, DAILY_SEND_LIMIT), ...noEmail.slice(0, MAX_WEBSITE_LOOKUPS)];

function classify(category, opportunity) {
  const s = `${category || ''} ${opportunity || ''}`.toLowerCase();
  if (/real estate|realtor|property|realty|broker/.test(s)) return { niche: 'Real Estate', angle: 'lead response and follow-up', pain: 'inquiries can go cold when response or follow-up is delayed' };
  if (/plumb|hvac|roof|roofing|electric|electrician|landscap|pest|cleaning|remodel|contractor|home service|garage door|solar/.test(s)) return { niche: 'Home Services', angle: 'missed-call handling and lead qualification', pain: 'new inquiries can be missed when crews or staff are busy' };
  if (/dentist|dental|orthodont|med spa|medical spa|clinic|doctor|dermat|chiropr|physio|health/.test(s)) return { niche: 'Dental / Medical / Med Spa', angle: 'inquiry handling and appointment booking', pain: 'staff spend time answering repetitive questions and coordinating bookings' };
  if (/law|attorney|legal/.test(s)) return { niche: 'Law Firms', angle: 'lead intake and qualification', pain: 'new inquiries need quick, structured intake before a team member can follow up' };
  if (/auto|automotive|car dealer|dealership|collision|mechanic|repair shop/.test(s)) return { niche: 'Automotive', angle: 'sales lead response and appointment follow-up', pain: 'sales inquiries need timely responses and consistent follow-up' };
  if (/marketing|advertis|digital agency|seo agency|lead generation agency|creative agency/.test(s)) return { niche: 'Marketing Agencies', angle: 'white-label automation for clients', pain: 'agencies can spend too much time manually building repetitive workflows for clients' };
  if (/ecommerce|e-commerce|shopify|online store|retail/.test(s)) return { niche: 'E-commerce', angle: 'customer support and order automation', pain: 'customers repeatedly ask about products, orders, delivery and status' };
  if (/gym|fitness|wellness|yoga|pilates|personal train/.test(s)) return { niche: 'Fitness & Wellness', angle: 'lead follow-up and booking', pain: 'new membership inquiries need quick responses and consistent follow-up' };
  if (/school|education|academy|training|college|university|tutor/.test(s)) return { niche: 'Education', angle: 'inquiry handling and follow-up', pain: 'prospective students and parents often need answers before taking the next step' };
  if (/hotel|motel|restaurant|cafe|salon|spa|hospitality/.test(s)) return { niche: 'Hospitality & Local Business', angle: 'customer inquiry and booking automation', pain: 'staff can be pulled into repetitive questions and booking requests' };
  if (/construction|industrial|manufactur|factory|logistics|warehouse/.test(s)) return { niche: 'Construction / Industrial', angle: 'internal workflow and inquiry automation', pain: 'repetitive coordination and information requests can consume staff time' };
  return { niche: category || 'Local Business', angle: 'customer inquiry and workflow automation', pain: 'repetitive inquiries and manual follow-up may be taking staff time' };
}

return picked.map(r => {
  const email = emailOf(r);
  const strategy = classify(r['Category'], r['Our Service Opportunity']);
  const website = String(r['Website'] || '').trim();
  return {
    json: {
      '#': r['#'],
      name: String(r['Business Name']).trim(),
      category: String(r['Category'] || '').trim(),
      address: String(r['Address'] || '').trim(),
      rating: r['Rating'] || '',
      reviews: r['Review Count'] || '',
      website,
      email,
      opportunity: String(r['Our Service Opportunity'] || '').trim(),
      niche: strategy.niche,
      angle: strategy.angle,
      likelyPain: strategy.pain,
      priority: String(r['Priority'] || '').trim(),
      sendLimit: DAILY_SEND_LIMIT,
      fetchUrl: (!email && website && !social.test(website)) ? website : ''
    }
  };
});

const leads = $('Pick Leads To Contact').all();
const homes = $input.all();

return homes.map((item, i) => {
  const lead = (leads[i] && leads[i].json) || {};
  const html = (item.json && typeof item.json.data === 'string') ? item.json.data : '';
  let contactUrl = '';

  if (html && lead.fetchUrl) {
    const re = /href\s*=\s*["']([^"'#][^"']*)["']/gi;
    let m;
    while ((m = re.exec(html)) !== null) {
      const href = m[1].trim();
      const low = href.toLowerCase();
      if (!low.includes('contact')) continue;
      if (/^(mailto:|tel:|javascript:)/.test(low)) continue;
      try {
        const abs = new URL(href, lead.fetchUrl).href;
        if (abs.replace(/\/$/, '') !== lead.fetchUrl.replace(/\/$/, '')) { contactUrl = abs; break; }
      } catch (e) {}
    }
  }
  return { json: { contact_url: contactUrl } };
});

const leads = $('Pick Leads To Contact').all();
const homes = $('Fetch Website').all();
const contacts = $('Fetch Contact Page').all();

const BAD = /(\.(png|jpe?g|gif|svg|webp|ico|css|js|woff2?)$)|sentry|wixpress|example\.|domain\.com|yourname|yourdomain|email@|@2x|u003e|noreply|no-reply|donotreply/i;
const PREFERRED = /^(info|contact|hello|hi|sales|office|admin|support|enquiries|inquiries|team|bookings|reservations|orders)@/;

function pickEmail(text, host) {
  const mailtos = [...text.matchAll(/mailto:([^"'?\s<>&]+)/gi)].map(m => {
    try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
  });
  const plain = text.match(/[a-zA-Z0-9._%+\-]+@[a-zA-Z0-9\-]+(?:\.[a-zA-Z0-9\-]+)*\.[a-zA-Z]{2,}/g) || [];
  const found = new Set();
  for (const e of [...mailtos, ...plain]) {
    const c = e.trim().toLowerCase().replace(/[.,;:]+$/, '');
    if (/^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/.test(c) && !BAD.test(c)) found.add(c);
  }
  const list = [...found];
  if (!list.length) return '';
  const root = (host || '').replace(/^www\./, '');
  const same = root ? list.filter(e => e.split('@')[1].endsWith(root)) : [];
  return same.find(e => PREFERRED.test(e)) || same[0] || list.find(e => PREFERRED.test(e)) || list[0];
}

function cleanHtml(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function usefulText(html) {
  const text = cleanHtml(html);
  // Keep the beginning and a few likely high-value sections without flooding the model.
  const chunks = text.split(/(?<=[.!?])\s+/).filter(x => x.length > 25);
  const useful = chunks.filter(x => !/cookie|privacy policy|terms of service|copyright|javascript|all rights reserved/i.test(x));
  return useful.slice(0, 35).join(' ').slice(0, 5000);
}

const limit = (leads[0] && leads[0].json.sendLimit) || 20;
const usedEmails = new Set();
const out = [];
let sendCount = 0;

leads.forEach((l, i) => {
  const lead = l.json;
  let email = lead.email || '';
  let source = email ? 'sheet' : '';
  const h = homes[i] && homes[i].json && typeof homes[i].json.data === 'string' ? homes[i].json.data : '';
  const c = contacts[i] && contacts[i].json && typeof contacts[i].json.data === 'string' ? contacts[i].json.data : '';
  const combined = (h + '\n' + c).replace(/\\\//g, '/');
  let websiteText = usefulText(combined);

  if (!email && lead.fetchUrl) {
    let host = '';
    try { host = new URL(lead.website).hostname; } catch (e) {}
    email = pickEmail(combined, host);
    source = email ? 'website' : '';
  }

  if (email) {
    if (usedEmails.has(email) || sendCount >= limit) return;
    usedEmails.add(email);
    sendCount++;
  }
  out.push({ json: { ...lead, email, emailSource: source, hasEmail: !!email, websiteEvidence: websiteText } });
});

return out;

const prompts = $('Prepare AI Prompt').all();
const ai = $input.all();

function parse(item) {
  try {
    const raw = String(item.json.choices?.[0]?.message?.content || '').replace(/```json|```/gi, '').trim();
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start < 0 || end <= start) return null;
    const o = JSON.parse(raw.slice(start, end + 1));
    if (o.subject && o.body) {
      return { subject: String(o.subject).trim(), body: String(o.body).trim() };
    }
  } catch (e) {}
  return null;
}

function fallback(l) {
  const angle = l.angle || 'customer inquiries and follow-up';
  const body = `I noticed ${l.name} focuses on ${l.category || 'serving customers'}${l.address ? ` in ${l.address.split(',')[0]}` : ''}. I had a quick thought around ${angle}: Octoflo helps businesses handle repetitive inquiries and follow-up automatically, so the team does not have to manage every step manually. If this is already handled well on your side, no worries. Would it be useful if I sent a short example of what this could look like?`;
  return { subject: `Quick idea for ${l.name}`, body };
}

return prompts.map((p, i) => {
  const l = p.json;
  const r = parse(ai[i]) || fallback(l);
  let body = r.body.replace(/^(hi|hello|dear)[^\n]*\n+/i, '').trim();
  // Keep the generated copy compact and remove accidental meta-language.
  body = body.replace(/\b(I hope you're doing well|hope you're doing well),?\s*/ig, '').trim();
  const subject = r.subject.replace(/[\r\n]+/g, ' ').replace(/^['"]|['"]$/g, '').trim().slice(0, 80);
  return {
    json: {
      '#': l['#'],
      name: l.name,
      email: l.email,
      subject,
      body: `Hi ${l.name} team,\n\n${body}\n\n${l.signature}`
    }
  };
});
